#include "reader/OfflineBook.h"
#include "reader/OfflineAccount.h"
#include "LauncherAssets.h"
#include "update/OnlineUpdate.h"
#include <QApplication>
#include <QTemporaryDir>
#include <QtTest/QTest>
#include <cassert>
#include <iostream>
int main(int argc,char **argv){QApplication app(argc,argv);QTemporaryDir t;assert(t.isValid());QString root=t.path();QJsonArray parts{QJsonObject{{"s",0},{"e",1},{"xps",QJsonArray{1,1}},{"xpe",QJsonArray{1,2}},{"url","000.js"}}};QJsonArray data{QJsonObject{{"t","p"},{"xp",QJsonArray{1,1}},{"c",QJsonArray{"Сохранённый текст"}}}};Fb3::OfflineBook b;assert(!b.open(root,"42","123"));assert(b.prepare(root,"42","123","Книга","https://www.litres.ru/download_book/123/456/",parts));assert(b.savePart(0,data));assert(b.part(0)==data);assert(b.savedParts()==1);assert(OfflineAccount::remember(root,"42"));assert(OfflineAccount::active(root)=="42");assert(!OfflineAccount::remember(root,"../secret"));assert(b.finish());Fb3::OfflineBook reopened;assert(reopened.open(root,"42","123"));assert(reopened.metadata()["complete"].toBool());assert(reopened.part(0)==data);assert(!reopened.open(root,"43","123"));assert(b.open(root,"42","123"));b.revoke();assert(!b.open(root,"42","123"));assert(b.prepare(root,"42","123","Новое издание","https://www.litres.ru/download_book/123/789/",parts));assert(b.part(0).isEmpty());assert(!b.metadata()["complete"].toBool());
 QString appPath=root+"/applications/litres.app";assert(LauncherAssets::atomic(appPath,"fake executable"));QJsonObject old{{"version","5"},{"applications",QJsonObject{{"PB_Settings",QJsonObject{{"title","Настройки"}}}}},{"view",QJsonObject{{"groups",QJsonArray{"preserve"}}}}};QString view=root+"/system/config/desktop/view.json";auto bytes=QJsonDocument(old).toJson();assert(LauncherAssets::atomic(view,bytes));QByteArray apple=QByteArray::fromHex("0005160700020000")+QByteArray(50,'\0');assert(LauncherAssets::atomic(root+"/applications/._litres.app",apple));assert(LauncherAssets::install(root,appPath));assert(!QFileInfo::exists(root+"/applications/._litres.app"));QFile f(view);assert(f.open(QIODevice::ReadOnly));auto config=QJsonDocument::fromJson(f.readAll()).object();assert(config["view"]==old["view"]);assert(config["applications"].toObject()["PB_Settings"]==old["applications"].toObject()["PB_Settings"]);assert(config["applications"].toObject()["U_litres"].toObject()["title"]=="Литрес");assert(QFileInfo::exists(view+".readerbook-backup"));assert(QFileInfo(root+"/applications/icons/readerbook.bmp").size()>0);assert(LauncherAssets::atomic(root+"/applications/._litres.app","this is another real file, keep it"));assert(!LauncherAssets::removeMacDuplicate(appPath));assert(QFileInfo::exists(root+"/applications/._litres.app"));
 OnlineUpdate dialog;dialog.resize(700,740);dialog.show();dialog.activateWindow();dialog.raise();QTest::qWait(100);auto *description=dialog.findChild<QTextBrowser *>();assert(description);description->setPlainText(QString::fromUtf8("Очень длинное описание обновления. ").repeated(300));QTest::qWait(60);assert(description->verticalScrollBar()->maximum()>0);description->setFocus();QTest::keyClick(description,Qt::Key_PageDown);assert(description->verticalScrollBar()->value()>0);QTest::keyClick(description,Qt::Key_PageUp);assert(description->verticalScrollBar()->value()==0);for(auto *button:dialog.findChildren<QPushButton *>()){assert(button->geometry().top()>=0);assert(button->geometry().bottom()<dialog.height());}QTest::keyClick(description,Qt::Key_Return);assert(qobject_cast<QPushButton *>(dialog.focusWidget()));dialog.grab().save("/tmp/update-long-notes.png");dialog.close();std::cout<<"PASS durable account-isolated cache; edition invalidation and revoked access; launcher preserves other apps and only deletes verified AppleDouble; long update notes scroll with physical keys and buttons remain visible\n";}
